function jump(nums: number[]): number {
  let jumps = 0;
  let currentEnd = 0; // правая граница зоны, достижимой за jumps прыжков
  let farthest = 0; // самый дальний индекс, достижимый за jumps + 1 прыжков

  // Последний индекс не перебираем: прыгать из него уже не нужно
  for (let i = 0; i < nums.length - 1; i++) {
    // Из любой точки текущего «уровня» пробуем прыгнуть как можно дальше
    farthest = Math.max(farthest, i + nums[i]);

    // Дошли до конца текущего уровня — нужен ещё один прыжок
    if (i === currentEnd) {
      jumps++;
      currentEnd = farthest;
      // Новый уровень уже накрывает последний индекс
      if (currentEnd >= nums.length - 1) break;
    }
  }

  return jumps;
}

// Время: O(n) — один проход
// Память: O(1)
